// Normaliza la respuesta a SIEMPRE 1 item con un array adentro,
// sin importar si la API devolvió un objeto único o un array de 0/1/N elementos.
return [{ json: { data: $input.all().map(i => i.json) } }];

// Los 4 inputs llegan ahora como 4 items reales (gracias a los nodos Merge),
// cada uno ya normalizado a { data: [...] } por los nodos "Normalizar *".
// Orden: kpis, productosEnRiesgo, bodegasCriticas, ordenesBorrador
const items = $input.all();

console.log('Items count:', items.length);
items.forEach((item, i) => console.log(`Item ${i}:`, JSON.stringify(item).substring(0, 200)));

// kpis es un recurso único: tomamos el primer (y único) elemento del array
const kpis = items[0]?.json?.data?.[0] ?? {};
// estos tres son listas: se quedan como array completo
const productosEnRiesgo = items[1]?.json?.data ?? [];
const bodegasCriticas = items[2]?.json?.data ?? [];
const ordenesBorrador = items[3]?.json?.data ?? [];

return [{
  json: {
    kpis,
    productosEnRiesgo,
    bodegasCriticas,
    ordenesBorrador
  }
}];

// El AI Agent devuelve texto (aunque le pidamos JSON), hay que parsearlo
const raw = $input.first().json;
let text = raw.output ?? raw.text ?? raw;

if (typeof text !== 'string') {
  return [{ json: text }];
}

// Quitar posibles cercas de markdown ```json ... ```
text = text.trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(text);
} catch (err) {
  throw new Error('La respuesta del AI Agent no es JSON válido: ' + err.message + ' | Texto recibido: ' + text.substring(0, 300));
}

return [{ json: parsed }];

// El backend ya devuelve proveedorId, bodegaDestinoId y precioUnitario
// reales en cada producto en riesgo (fix aplicado en InventarioAnalyticsServiceImpl).
// Los defaults de abajo quedan SOLO como fallback de seguridad, por si algún
// producto no tiene proveedor/bodega asignada todavía.
const productos = $('Merge MCP Data').first().json.productosEnRiesgo || [];

const PROVEEDOR_ID_FALLBACK = 1;
const BODEGA_DESTINO_ID_FALLBACK = 1;
const PRECIO_UNITARIO_FALLBACK = 100;

return productos
  .filter(p => p.estado === 'EN_RIESGO')
  .map(p => {
    const cantidad = Math.ceil(Math.max(1, (p.puntoReorden * 2) - p.stockTotal));
    const proveedorId = p.proveedorId ?? PROVEEDOR_ID_FALLBACK;
    const bodegaDestinoId = p.bodegaDestinoId ?? BODEGA_DESTINO_ID_FALLBACK;
    const precioUnitario = p.precioUnitario ?? PRECIO_UNITARIO_FALLBACK;

    if (p.proveedorId == null || p.bodegaDestinoId == null || p.precioUnitario == null) {
      console.log(`Producto ${p.productoId} (${p.nombre}) usó algún fallback: proveedorId=${proveedorId}, bodegaDestinoId=${bodegaDestinoId}, precioUnitario=${precioUnitario}`);
    }

    return {
      json: {
        productoId: p.productoId,
        proveedorId,
        bodegaDestinoId,
        cantidad,
        precioUnitario,
        _productoNombre: p.nombre,
        _proveedorNombre: p.proveedor
      }
    };
  });

// crear_orden_borrador corrió una vez por producto (n8n itera items automáticamente).
// Aquí agrupamos todas las órdenes creadas en un solo item para el resumen.
const items = $input.all();
return [{
  json: {
    ordenesCreadas: items.map(i => i.json)
  }
}];
